import React, { useState, useEffect } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import About from './pages/About';
import Contact from './pages/Contact';
import Services from './pages/Services';
import Products from './pages/Products';
import Dashboard from './pages/Dashboard';
import Login from './pages/Login';
import ProtectedRoute from './components/ProtectedRoute';
import LoadingScreen from './components/LoadingScreen';

function App() {
  const [isLottieDataLoaded, setIsLottieDataLoaded] = useState(false);
  const [isAppContentLoaded, setIsAppContentLoaded] = useState(false);
  const [lottieAnimationData, setLottieAnimationData] = useState(null);

  useEffect(() => {
    // Fetch Lottie animation data from public folder
    fetch('/Animation - 1750150537070.lottie')
      .then(response => {
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        return response.json();
      })
      .then(data => {
        setLottieAnimationData(data);
        setIsLottieDataLoaded(true);
      })
      .catch(error => {
        console.error("Error loading Lottie animation:", error);
        // Fallback or handle error if animation fails to load
        setIsLottieDataLoaded(true); // Allow app to load even if animation fails
      });

    // Simulate main app content loading time
    const appLoadTimer = setTimeout(() => {
      setIsAppContentLoaded(true);
    }, 2000); // Show loading screen for at least 2 seconds

    return () => {
      clearTimeout(appLoadTimer);
    };
  }, []);

  // Show loading screen until both Lottie data and app content are loaded
  const showLoadingScreen = !isLottieDataLoaded || !isAppContentLoaded;

  return (
    <div className="min-h-screen bg-gray-50">
      {showLoadingScreen && lottieAnimationData && (
        <LoadingScreen animationData={lottieAnimationData} isLoading={showLoadingScreen} />
      )}
      {!showLoadingScreen && (
        <>
          <Navbar />
          <main>
            <Routes>
              <Route path="/" element={<Home />} />
              <Route path="/about" element={<About />} />
              <Route path="/contact" element={<Contact />} />
              <Route path="/services" element={<Services />} />
              <Route path="/products" element={<Products />} />
              <Route path="/login" element={<Login />} />
              <Route path="/dashboard" element={
                <ProtectedRoute>
                  <Dashboard />
                </ProtectedRoute>
              } />
              <Route path="*" element={<Navigate to="/" replace />} />
            </Routes>
          </main>
          <Footer />
        </>
      )}
    </div>
  );
}

export default App;
